local function circlePts(cx, cy, r, seg)
    local pts = {}
    do
        local i = 0
        while i < seg do
            local a = i / seg * math.pi * 2
            pts[#pts + 1] = Vec2(
                cx + math.cos(a) * r,
                cy + math.sin(a) * r
            )
            i = i + 1
        end
    end
    return pts
end
local function ring(d, cx, cy, r, seg, w, c, a0, a1)
    local from = a0 == nil and 0 or a0
    local to = a1 == nil and math.pi * 2 or a1
    local px = cx + math.cos(from) * r
    local py = cy + math.sin(from) * r
    do
        local i = 1
        while i <= seg do
            local ang = from + (to - from) * i / seg
            local nx = cx + math.cos(ang) * r
            local ny = cy + math.sin(ang) * r
            d:drawSegment(
                Vec2(px, py),
                Vec2(nx, ny),
                w,
                c
            )
            px = nx
            py = ny
            i = i + 1
        end
    end
end
local function rectPts(x, y, w, h)
