        Vec2(x + w, y),
        Vec2(x + w, y + h),
        Vec2(x, y + h)
    }
end
local function sectorPts(cx, cy, r, a0, a1, seg)
    local pts = {Vec2(cx, cy)}
    do
        local i = 0
        while i <= seg do
            local a = a0 + (a1 - a0) * i / seg
            pts[#pts + 1] = Vec2(
                cx + math.cos(a) * r,
                cy + math.sin(a) * r
            )
            i = i + 1
        end
    end
