    local function drawFigure(d, x, y, s, a, female, pose)
        if a <= 0.01 then
            return
        end
        local c = col(Palette.inkDark, a)
        local lw = 3 * s
        local function seg(x1, y1, x2, y2)
            d:drawSegment(
                Vec2(x + x1 * s, y + y1 * s),
                Vec2(x + x2 * s, y + y2 * s),
                lw,
                c
            )
        end
        if pose == "lie" then
            d:drawDot(
                Vec2(x - 16 * s, y + 5 * s),
                4.5 * s,
                c
            )
            seg(-10, 5, 14, 7)
            seg(14, 7, 32, 3)
            seg(-10, 6, 6, 12)
            return
        end
        if pose == "kneel" then
            d:drawDot(
                Vec2(x, y + 24 * s),
                4.5 * s,
                c
            )
            seg(0, 20, 0, 8)
            seg(0, 8, -8, 2)
            seg(0, 8, 6, 1)
            seg(0, 17, 9, 9)
            seg(0, 15, -7, 9)
            if female then
                d:drawSegment(
                    Vec2(x - 3 * s, y + 26 * s),
                    Vec2(x - 9 * s, y + 18 * s),
                    lw * 0.9,
                    c
                )
            end
            return
        end
        d:drawDot(
            Vec2(x, y + 30 * s),
            4.5 * s,
            c
        )
        seg(0, 26, 0, 12)
        if pose == "walk" then
            seg(0, 12, -7 * s, 0)
            seg(0, 12, 7 * s, 0)
            seg(0, 23, -6 * s, 16)
            seg(0, 23, 6 * s, 17)
        elseif pose == "push" then
            seg(0, 12, -6 * s, 0)
            seg(0, 12, 6 * s, 0)
            seg(0, 24, 12 * s, 22)
            seg(0, 22, 13 * s, 18)
        else
            seg(0, 12, -5 * s, 0)
            seg(0, 12, 5 * s, 0)
            seg(0, 23, -6 * s, 15)
            seg(0, 23, 6 * s, 15)
        end
        if female then
            d:drawSegment(
                Vec2(x - 3 * s, y + 32 * s),
                Vec2(x - 10 * s, y + 24 * s),
                lw * 0.9,
                c
            )
            d:drawSegment(
                Vec2(x + 7 * s, y + 16 * s),
                Vec2(x + 16 * s, y + 4 * s),
                2 * s,
                col(Palette.paleInk, a)
            )
            d:drawDot(
                Vec2(x + 8 * s, y + 17 * s),
                1.8 * s,
                c
            )
        elseif pose == "back" then
            d:drawSegment(
                Vec2(x - 6 * s, y + 8 * s),
                Vec2(x + 8 * s, y + 30 * s),
                2 * s,
                col(Palette.paleInk, a)
            )
        else
            d:drawDot(
                Vec2(x, y + 34 * s),
                2 * s,
                c
            )
        end
    end
    local function drawBandit(d, x, y, s, a)
